#include <stack>

using namespace std;

int main() {
    string s;
    if (cin >> s) {
        stack<char> st;
        bool ok = true;
        for (char c : s) {
            if (c == '(' || c == '{' || c == '[') st.push(c);
            else {
                if (st.empty()) { ok = false; break; }
                char top = st.top(); st.pop();
                if (c == ')' && top != '(') { ok = false; break; }
                if (c == '}' && top != '{') { ok = false; break; }
                if (c == ']' && top != '[') { ok = false; break; }
            }
        }
        if (ok && st.empty()) cout << "true" << endl;
        else cout << "false" << endl;
    }
    return 0;
}

